(1, 1, 'Service Agreement Template', 'Service', 'Standard service agreement template', '<h1>Service Agreement</h1>\r\n<p><strong>Contract Number:</strong> {CONTRACT_NUMBER}</p>\r\n<p><strong>Date:</strong> {CONTRACT_DATE}</p>\r\n<p><strong>Valid Until:</strong> {VALID_UNTIL}</p>\r\n\r\n<h2>Parties</h2>\r\n<p><strong>Service Provider:</strong> {COMPANY_NAME}<br>\r\n{COMPANY_ADDRESS}<br>\r\n{COMPANY_PHONE}<br>\r\n{COMPANY_EMAIL}</p>\r\n\r\n<p><strong>Client:</strong> {CLIENT_NAME}<br>\r\n{CLIENT_ADDRESS}</p>\r\n\r\n<h2>Services</h2>\r\n{ITEMS_LIST}\r\n\r\n<h2>Terms and Conditions</h2>\r\n<p>1. The service provider agrees to deliver the services as described above.</p>\r\n<p>2. The client agrees to pay the total amount of {CONTRACT_AMOUNT} as specified.</p>\r\n<p>3. Payment terms: {PAYMENT_TERMS}</p>\r\n<p>4. This contract is valid from {CONTRACT_DATE} until {VALID_UNTIL}.</p>\r\n\r\n<h2>Additional Terms</h2>\r\n{ADDITIONAL_TERMS}\r\n\r\n<p><strong>Signature:</strong></p>\r\n<p>Service Provider: ___________________ Date: ___________</p>\r\n<p>Client: ___________________ Date: ___________</p>', '{\"CONTRACT_NUMBER\": \"Contract Number\", \"CONTRACT_DATE\": \"Contract Date\", \"VALID_UNTIL\": \"Valid Until Date\", \"COMPANY_NAME\": \"Company Name\", \"CLIENT_NAME\": \"Client Name\", \"CONTRACT_AMOUNT\": \"Total Amount\", \"ITEMS_LIST\": \"Items List\", \"ADDITIONAL_TERMS\": \"Additional Terms\"}', 1, 1, 1, '2026-01-27 08:37:10', '2026-01-27 08:37:10', 0),
(2, 1, 'Product Sales Agreement', 'Product', 'Standard product sales contract template', '<h1>Product Sales Agreement</h1>\r\n<p><strong>Contract Number:</strong> {CONTRACT_NUMBER}</p>\r\n<p><strong>Date:</strong> {CONTRACT_DATE}</p>\r\n\r\n<h2>Parties</h2>\r\n<p><strong>Seller:</strong> {COMPANY_NAME}</p>\r\n<p><strong>Buyer:</strong> {CLIENT_NAME}</p>\r\n\r\n<h2>Products</h2>\r\n{ITEMS_LIST}\r\n\r\n<h2>Payment Terms</h2>\r\n<p>Total Amount: {CONTRACT_AMOUNT}</p>\r\n<p>Payment Terms: {PAYMENT_TERMS}</p>\r\n\r\n<h2>Delivery Terms</h2>\r\n<p>{DELIVERY_TERMS}</p>\r\n\r\n<h2>Warranty</h2>\r\n<p>{WARRANTY_TERMS}</p>\r\n\r\n<p><strong>Signatures:</strong></p>\r\n<p>Seller: ___________________ Date: ___________</p>\r\n<p>Buyer: ___________________ Date: ___________</p>', '{\"CONTRACT_NUMBER\": \"Contract Number\", \"CONTRACT_DATE\": \"Contract Date\", \"COMPANY_NAME\": \"Company Name\", \"CLIENT_NAME\": \"Client Name\", \"CONTRACT_AMOUNT\": \"Total Amount\", \"ITEMS_LIST\": \"Items List\"}', 0, 1, 1, '2026-01-27 08:37:10', '2026-01-27 08:37:10', 0),
(3, 1, 'Employment Contract Template', 'Employment', 'Standard employment contract template', '<h1>Employment Contract</h1>\r\n<p><strong>Contract Number:</strong> {CONTRACT_NUMBER}</p>\r\n<p><strong>Date:</strong> {CONTRACT_DATE}</p>\r\n\r\n<h2>Parties</h2>\r\n<p><strong>Employer:</strong> {COMPANY_NAME}</p>\r\n<p><strong>Employee:</strong> {CLIENT_NAME}</p>\r\n\r\n<h2>Position and Responsibilities</h2>\r\n<p>{POSITION_DESCRIPTION}</p>\r\n\r\n<h2>Compensation</h2>\r\n<p>Salary: {CONTRACT_AMOUNT}</p>\r\n<p>Payment Terms: {PAYMENT_TERMS}</p>\r\n\r\n<h2>Term of Employment</h2>\r\n<p>Start Date: {CONTRACT_DATE}</p>\r\n<p>End Date: {VALID_UNTIL}</p>\r\n\r\n<h2>Terms and Conditions</h2>\r\n{ADDITIONAL_TERMS}\r\n\r\n<p><strong>Signatures:</strong></p>\r\n<p>Employer: ___________________ Date: ___________</p>\r\n<p>Employee: ___________________ Date: ___________</p>', '{\"CONTRACT_NUMBER\": \"Contract Number\", \"CONTRACT_DATE\": \"Contract Date\", \"VALID_UNTIL\": \"End Date\", \"COMPANY_NAME\": \"Company Name\", \"CLIENT_NAME\": \"Employee Name\", \"CONTRACT_AMOUNT\": \"Salary\", \"POSITION_DESCRIPTION\": \"Position Description\"}', 0, 1, 1, '2026-01-27 08:37:10', '2026-01-27 08:37:10', 0),
(4, 2, 'sevicess', 'NDA', 'okk', '<p>okk</p>', NULL, 0, 1, 2, '2026-01-27 13:41:50', '2026-01-27 13:41:50', 0);

