INSERT INTO `email_templates` (`id`, `company_id`, `name`, `subject`, `body`, `type`, `template_key`, `category`, `is_active`, `created_at`, `updated_at`, `is_deleted`) VALUES
(1, 1, 'Estimate Sent', 'Estimate #{ESTIMATE_NUMBER} from {COMPANY_NAME}', 'Dear {CLIENT_NAME},\n\nPlease find the attached estimate #{ESTIMATE_NUMBER} for {TOTAL_AMOUNT}.\n\nYou can view the estimate online here: {ESTIMATE_URL}\n\nWe look forward to your business.\n\nBest regards,\n{COMPANY_NAME}', 'estimate', 'legacy_1', '', 1, '2026-01-17 12:52:15', '2026-01-19 09:54:57', 0),
(2, 1, 'Estimate Accepted', 'Estimate #{ESTIMATE_NUMBER} Accepted', 'Dear {CLIENT_NAME},\n\nThank you for accepting Estimate #{ESTIMATE_NUMBER}.\n\nWe will proceed with the next steps shortly.\n\nBest regards,\n{COMPANY_NAME}', 'estimate', 'legacy_2', '', 1, '2026-01-17 12:52:15', '2026-01-19 09:54:57', 0),
(3, 1, 'Estimate Rejected', 'Estimate #{ESTIMATE_NUMBER} Rejected', 'Dear {CLIENT_NAME},\n\nWe received your notification regarding Estimate #{ESTIMATE_NUMBER}.\n\nIf you have any questions or feedback, please let us know.\n\nBest regards,\n{COMPANY_NAME}', 'estimate', 'legacy_3', '', 1, '2026-01-17 12:52:15', '2026-01-19 09:54:57', 0),
(4, 2, 'Contract sent', 'Contract sent', '<div style=\"text-align: center; background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); padding: 30px; border-radius: 8px 8px 0 0;\"><h1 style=\"color: white; margin: 0; font-size: 24px; font-weight: bold;\"><span style=\"font-size: 14px; letter-spacing: -0.01em; background: rgb(227, 242, 253); padding: 2px 6px; border-radius: 3px; font-family: monospace; color: rgb(25, 118, 210);\">{{CONTACT_FIRST_NAME}}</span><span style=\"background-color: initial; color: rgb(31, 41, 55); font-size: 14px; letter-spacing: -0.01em;\">&nbsp;</span><span style=\"font-size: 14px; letter-spacing: -0.01em; background: rgb(227, 242, 253); padding: 2px 6px; border-radius: 3px; font-family: monospace; color: rgb(25, 118, 210);\">{{CONTACT_LAST_NAME}}</span><span style=\"background-color: initial; color: rgb(31, 41, 55); font-size: 14px; letter-spacing: -0.01em;\">&nbsp;</span><span style=\"font-size: 14px; letter-spacing: -0.01em; background: rgb(227, 242, 253); padding: 2px 6px; border-radius: 3px; font-family: monospace; color: rgb(25, 118, 210);\">{{PROJECT_TITLE}}</span><span style=\"background-color: initial; color: rgb(31, 41, 55); font-size: 14px; letter-spacing: -0.01em;\">&nbsp;</span><span style=\"background-color: initial; letter-spacing: -0.01em;\">CONTRACT #{CONTRACT_ID}</span></h1>\n</div>\n<div style=\"padding: 30px; background: #fff;\">\n  <p style=\"color: #333; line-height: 1.6;\">Hello {CONTACT_FIRST_NAME},</p>\n  <p style=\"color: #333; line-height: 1.6;\">Here is a contract for you.</p>\n  <p style=\"margin: 20px 0;\">\n    <a href=\"{PUBLIC_CONTRACT_URL}\" style=\"display: inline-block; background: #17a2b8; color: white; padding: 12px 24px; text-decoration: none; border-radius: 4px; font-weight: bold;\">Show Contract</a>\n  </p>\n  <p style=\"color: #666; font-size: 14px;\">Public URL: {PUBLIC_CONTRACT_URL}</p>\n  <p style=\"color: #333; margin-top: 30px;\">{SIGNATURE}</p>\n</div>', 'contract_sent', '', '', 1, '2026-01-20 09:03:02', '2026-01-20 09:03:32', 0),
(6, 2, 'Contract accepted', 'Contract accepted', '<div style=\"padding: 30px;\">\n  <h2 style=\"color: #27ae60;\">Contract Accepted</h2>\n  <p>Hello {CONTACT_FIRST_NAME},</p>\n  <p>Great news! Your contract #{CONTRACT_ID} has been accepted.</p>\n  <p>{SIGNATURE}</p>\n</div>', 'contract_accepted', 'contract_accepted', 'contract', 1, '2026-01-20 09:52:17', '2026-01-20 09:52:17', 0),
(7, 2, 'Contract rejected', 'Contract rejected', '<div style=\"padding: 30px;\">\n  <h2 style=\"color: #e74c3c;\">Contract Rejected</h2>\n  <p>Hello {CONTACT_FIRST_NAME},</p>\n  <p>Unfortunately, contract #{CONTRACT_ID} has been rejected.</p>\n  <p>{SIGNATURE}</p>\n</div>', 'contract_rejected', 'contract_rejected', 'contract', 1, '2026-01-20 09:52:20', '2026-01-20 09:52:20', 0),
